 secondary=["exterminator Orlando", "bed bug exterminator Orlando", "mosquito control Orlando"],
 hoods=["Thornton Park", "College Park", "Baldwin Park", "Lake Nona", "MetroWest", "Audubon Park", "Delaney Park", "Colonialtown", "Mills 50", "Conway", "Lake Eola Heights", "Dr. Phillips area"],
 lead="Orlando is a city of lakes, from Lake Eola downtown to the chains around College Park and Conway, and that water, plus heat, humidity and constant visitors, keeps termites, ants, mosquitoes and bed bugs on the move.",
